/**
 * GDD §9.2 — Member roster.
 *
 * Every member with their Power Points split into "power from the units they
 * command" and "power from the ground they hold" — shown separately AND as a
 * stacked bar — plus owned hexes, stockpiles, online status, army count and
 * army positions with tap-to-focus on the global map.
 *
 * Sortable by power, tiles and activity. Leaders get appoint / demote / kick /
 * transfer-leadership controls, every one of them behind a hold-to-confirm ring
 * and gated by the §8 permission matrix.
 */
import type { IBackend } from '../../backend/IBackend';
import { GUILD } from '../../config/balance';
import { can, roleOf } from '../../game/guild/permissions';
import { rosterOf, type RosterArmy, type RosterRow } from '../../game/guild/power';
import { focusHex, game, setScreen } from '../../game/store';
import type { GameState, GuildRole, HexId, PlayerId, Result } from '../../game/types';
import {
  badge,
  button,
  emptyState,
  holdButton,
  ICONS,
  powerBar,
  sectionHeader,
  statRow,
  toast,
} from '../components';
import { clear, el, fmtAgo, fmtNum, haptic, svg as svgEl } from '../dom';

// ─────────────────────────────────────────────────────────────────────────────
// Career recorder
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The season summary (GDD §11) wants "peak power" and "peak hexes held", but
 * `GameState` only ever carries the present tense. This module-scoped recorder
 * samples the authoritative store from the moment the guild panel is first
 * opened, so the end-of-season dossier can report an honest observed peak
 * alongside the timestamp it started watching.
 */
export interface CareerRecord {
  peakPower: number;
  peakHexes: number;
  peakArmies: number;
  /** Simulated clock at the first sample, 0 while nothing has been seen. */
  since: number;
  samples: number;
}

const career: CareerRecord = {
  peakPower: 0,
  peakHexes: 0,
  peakArmies: 0,
  since: 0,
  samples: 0,
};

let lastSampleAt = 0;

game.subscribe((state) => {
  if (!state) return;
  // 2 Hz of simulated clock is plenty — the backend pushes far faster.
  if (state.now - lastSampleAt < 500) return;
  lastSampleAt = state.now;

  const me = state.players[state.meId];
  if (!me?.guildId) return;
  const rows = rosterOf(state, me.guildId);
  const mine = rows.find((r) => r.playerId === state.meId);
  if (!mine) return;

  if (career.since === 0) career.since = state.now;
  career.samples++;
  career.peakPower = Math.max(career.peakPower, mine.power.total);
  career.peakHexes = Math.max(career.peakHexes, mine.hexCount);
  career.peakArmies = Math.max(career.peakArmies, mine.armyCount);
});

/** Observed peaks for the player, since the recorder started watching. */
export function careerRecord(): Readonly<CareerRecord> {
  return career;
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared atoms (reused by the objectives + transfers tabs and the season screen)
// ─────────────────────────────────────────────────────────────────────────────

const MARK_FRAME = 'M32 4l24.2 14v28L32 60 7.8 46V18z';

function initialsOf(name: string): string {
  const parts = name.trim().split(/[\s.-]+/).filter(Boolean);
  if (parts.length === 0) return '??';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export interface CommanderMarkOpts {
  /** Draw the rotating "this is you" ring. */
  me?: boolean;
  /** Dim the initials for AI-driven commanders. */
  bot?: boolean;
  /** Solid ring instead of the hex frame (used for the committed-crew stack). */
  round?: boolean;
  title?: string;
}

/**
 * Procedural commander mark: a hex-framed monogram tinted by the player's
 * stored hue, so the same commander always reads the same colour everywhere.
 */
export function commanderMark(
  player: { name: string; hue: number },
  opts: CommanderMarkOpts = {},
): HTMLElement {
  const tint = `hsl(${Math.round(player.hue)}, 82%, 64%)`;
  const classes = ['cmark'];
  if (opts.me) classes.push('is-me');
  if (opts.bot) classes.push('is-bot');

  const wrap = el('span', {
    class: classes.join(' '),
    style: `--mark:${tint}`,
    aria: { label: player.name },
    attrs: { title: opts.title ?? player.name },
  });

  const shape = opts.round
    ? `<circle cx="32" cy="32" r="27" />`
    : `<path d="${MARK_FRAME}" />`;

  wrap.appendChild(
    svgEl(
      `<svg viewBox="0 0 64 64" aria-hidden="true">
         <g fill="${tint}" fill-opacity="0.16" stroke="${tint}" stroke-width="3"
            stroke-linejoin="round">${shape}</g>
       </svg>`,
    ),
  );
  wrap.appendChild(el('b', { text: initialsOf(player.name) }));
  return wrap;
}

export interface HexChipOpts {
  /** Extra text after the coordinates (e.g. an army size). */
  suffix?: string;
  tone?: 'default' | 'hot' | 'gold';
  /** Override the default focus-the-map behaviour. */
  onClick?: () => void;
}

/** Tappable hex reference. Focuses the global map and routes there. */
export function hexChip(hexId: HexId, opts: HexChipOpts = {}): HTMLElement {
  const classes = ['hexchip'];
  if (opts.tone === 'hot') classes.push('hexchip--hot');
  if (opts.tone === 'gold') classes.push('hexchip--gold');

  const label = opts.suffix ? `${hexId} · ${opts.suffix}` : hexId;
  const node = el('button', {
    class: classes.join(' '),
    attrs: { type: 'button' },
    aria: { label: `focus hex ${hexId}` },
    text: label,
  });
  node.addEventListener('click', (ev) => {
    ev.stopPropagation();
    haptic(10);
    if (opts.onClick) {
      opts.onClick();
      return;
    }
    focusHex(hexId);
    setScreen('map');
  });
  return node;
}

/** Awaits a backend call and surfaces `ok === false` as a toast. */
export async function runAction<T>(
  label: string,
  call: Promise<Result<T>>,
): Promise<T | undefined> {
  const res = await call;
  if (!res.ok) {
    toast({ title: 'REJECTED', body: res.error, kind: 'bad' });
    return undefined;
  }
  toast({ title: label, kind: 'ok' });
  return res.value;
}

/**
 * The authoritative simulated clock. The offline world runs `SIM.timeScale`
 * faster than wall time, so every countdown in the guild + diplomacy screens
 * has to read from here rather than from `Date.now()`.
 */
export function simNow(): number {
  return game.get()?.now ?? Date.now();
}

/** Shared shape every guild tab implements. */
export interface GuildTabView {
  readonly el: HTMLElement;
  sync(state: GameState): void;
  dispose(): void;
}

const ROLE_BADGE: Record<GuildRole, 'gold' | 'violet' | 'default'> = {
  leader: 'gold',
  officer: 'violet',
  member: 'default',
};

/**
 * Collapsed rows are ~160px wide once the rank, sigil and power readout have
 * taken their share, which will not hold a name plus "OFFICER" plus "DIPLOMAT".
 * The head only has to signal rank — the drawer beneath it spells the role out
 * in full alongside its controls — so the badges abbreviate here and carry the
 * full word as a tooltip.
 */
const ROLE_SHORT: Record<GuildRole, string> = {
  leader: 'LEAD',
  officer: 'OFCR',
  member: '',
};

function roleBadge(text: string, title: string, kind: Parameters<typeof badge>[1]): HTMLElement {
  const node = badge(text, kind);
  node.title = title;
  return node;
}

// ─────────────────────────────────────────────────────────────────────────────
// Roster tab
// ─────────────────────────────────────────────────────────────────────────────

type SortKey = 'power' | 'tiles' | 'activity';

const SORTS: { key: SortKey; label: string }[] = [
  { key: 'power', label: 'POWER' },
  { key: 'tiles', label: 'TILES' },
  { key: 'activity', label: 'ACTIVITY' },
];

function sortRows(rows: RosterRow[], key: SortKey): RosterRow[] {
  const out = [...rows];
  if (key === 'tiles') {
    out.sort((a, b) => b.hexCount - a.hexCount || b.power.total - a.power.total);
  } else if (key === 'activity') {
    out.sort(
      (a, b) =>
        Number(b.online) - Number(a.online) ||
        b.lastSeen - a.lastSeen ||
        b.power.total - a.power.total,
    );
  } else {
    out.sort((a, b) => b.power.total - a.power.total || a.name.localeCompare(b.name));
  }
  return out;
}

interface RowView {
  root: HTMLElement;
  update(row: RosterRow, state: GameState, rank: number): void;
}

function armyLine(army: RosterArmy, state: GameState): HTMLElement {
  const line = el('div', { class: 'rarmy' });
  line.appendChild(el('span', { class: 'rarmy__name', text: army.name }));

  if (army.besieging) line.appendChild(badge('SIEGE', 'hot'));
  else if (army.moving) line.appendChild(badge('MOVING', 'violet'));

  line.appendChild(
    hexChip(army.hexId, {
      suffix: `${army.unitCount}U`,
      tone: army.besieging ? 'hot' : army.moving ? 'gold' : 'default',
    }),
  );

  if (army.moving && army.arrivesAt !== undefined) {
    const secs = Math.max(0, Math.round((army.arrivesAt - state.now) / 1000));
    line.appendChild(
      el('span', {
        class: 'mono dim-2',
        style: 'font-size:9px;white-space:nowrap',
        text: `ETA ${secs}s`,
      }),
    );
  }
  return line;
}

export function createRosterTab(backend: IBackend): GuildTabView {
  const root = el('div', { class: 'gpane' });

  // ── sort bar ──────────────────────────────────────────────────────────────
  let sortKey: SortKey = 'power';
  const sortBar = el('div', { class: 'rsort' }, el('span', { class: 'rsort__label', text: 'SORT' }));
  const sortButtons = new Map<SortKey, HTMLButtonElement>();
  for (const def of SORTS) {
    const btn = el('button', {
      class: 'rsort__btn',
      attrs: { type: 'button' },
      text: def.label,
    });
    btn.addEventListener('click', () => {
      if (sortKey === def.key) return;
      sortKey = def.key;
      haptic(9);
      for (const [k, b] of sortButtons) b.classList.toggle('is-on', k === sortKey);
      if (lastState) render(lastState);
    });
    sortButtons.set(def.key, btn);
    sortBar.appendChild(btn);
  }
  sortButtons.get('power')?.classList.add('is-on');

  const capNote = el('span', { class: 'mono dim-2', style: 'font-size:9px;margin-left:auto' });
  sortBar.appendChild(capNote);

  const list = el('div', { class: 'rlist' });
  const scroll = el('div', { class: 'gscroll' }, list);
  root.appendChild(sortBar);
  root.appendChild(scroll);

  const views = new Map<PlayerId, RowView>();
  const open = new Set<PlayerId>();
  let lastState: GameState | null = null;
  let orderKey = '';

  // ── one member row ────────────────────────────────────────────────────────
  function buildRow(playerId: PlayerId, seed: RosterRow, state: GameState): RowView {
    const meId = state.meId;
    const isMe = playerId === meId;

    const rank = el('span', { class: 'rrow__rank', text: '—' });
    const markSlot = el('span', { class: 'row', style: 'flex:none' });
    const nameLine = el('div', { class: 'rrow__name' });
    const subLine = el('div', { class: 'rrow__sub' });
    const total = el('span', { class: 'rrow__pwtot', text: '0' });
    const miniUnit = el('i');
    const miniTerr = el('i');
    const mini = el('div', { class: 'rrow__mini' }, miniUnit, miniTerr);

    const chev = svgEl(ICONS.chevronDown);
    chev.setAttribute('class', 'rrow__chev');

    const head = el(
      'button',
      { class: 'rrow', attrs: { type: 'button' }, aria: { expanded: 'false' } },
      rank,
      markSlot,
      el('div', { class: 'rrow__id' }, nameLine, subLine),
      el('div', { class: 'rrow__pw' }, total, mini),
      chev,
    );

    const powerSlot = el('div');
    const statsSlot = el('div', { class: 'rgrid' });
    const armiesSlot = el('div', { class: 'col' });
    const controlsSlot = el('div');
    const drawer = el(
      'div',
      { class: 'rdraw' },
      powerSlot,
      statsSlot,
      sectionHeader('COLUMNS'),
      armiesSlot,
      controlsSlot,
    );

    const rootEl = el(
      'div',
      { class: isMe ? 'rmem rmem--me' : 'rmem' },
      head,
      drawer,
    );

    head.addEventListener('click', () => {
      haptic(9);
      if (open.has(playerId)) open.delete(playerId);
      else open.add(playerId);
      const isOpen = open.has(playerId);
      rootEl.classList.toggle('is-open', isOpen);
      head.setAttribute('aria-expanded', String(isOpen));
      if (isOpen && lastState) refreshDrawer(lastState, currentRow, true);
    });

    let currentRow: RosterRow = seed;
    let markKey = '';
    let nameKey = '';
    let subKey = '';
    let statsKey = '';
    let armyKey = '';
    let ctlKey = '';

    function refreshDrawer(s: GameState, row: RosterRow, force: boolean): void {
      if (!open.has(playerId)) return;

      // ── the §9.2 split, spelled out ──
      const nextStats = `${row.power.unitPower}|${row.power.territoryPower}|${row.hexCount}|${Math.round(
        row.minerals,
      )}|${Math.round(row.gas)}|${row.unitCount}|${row.reserveCount}`;
      if (force || nextStats !== statsKey) {
        statsKey = nextStats;
        clear(powerSlot);
        powerSlot.appendChild(powerBar(row.power.unitPower, row.power.territoryPower));

        clear(statsSlot);
        const cell = (k: string, v: string, tone?: 'hot' | 'gold'): HTMLElement =>
          el(
            'div',
            { class: 'gstat' },
            el('span', { class: 'gstat__k', text: k }),
            el('span', {
              class: `gstat__v${tone === 'hot' ? ' is-hot' : tone === 'gold' ? ' is-gold' : ''}`,
              text: v,
            }),
          );
        statsSlot.appendChild(cell('TILES', String(row.hexCount)));
        statsSlot.appendChild(cell('MINERALS', fmtNum(row.minerals), 'hot'));
        statsSlot.appendChild(cell('GAS', fmtNum(row.gas), 'gold'));
        statsSlot.appendChild(cell('UNITS', String(row.unitCount)));

        const yieldRow = statRow(
          'HOURLY YIELD',
          `${fmtNum(row.power.yieldPerHour.m)} M · ${fmtNum(row.power.yieldPerHour.g)} G`,
        );
        statsSlot.appendChild(
          el('div', { style: 'grid-column:1/-1' }, yieldRow, statRow(
            'IN RESERVE',
            `${row.reserveCount} unit${row.reserveCount === 1 ? '' : 's'} garrisoned`,
          )),
        );
      }

      const nextArmies =
        row.armies.map((a) => `${a.armyId}:${a.hexId}:${a.unitCount}:${a.moving}:${a.besieging}`).join('|') ||
        'none';
      if (force || nextArmies !== armyKey) {
        armyKey = nextArmies;
        clear(armiesSlot);
        if (row.armies.length === 0) {
          armiesSlot.appendChild(emptyState('◇', 'no columns in the field'));
        } else {
          for (const army of row.armies) armiesSlot.appendChild(armyLine(army, s));
        }
      }

      // ── leadership controls, gated by the §8 matrix ──
      const mayAppoint = can(s, meId, 'appoint');
      const mayKick = can(s, meId, 'kick');
      const myRole = roleOf(s, meId) ?? 'member';
      const nextCtl = `${row.role}|${row.isDiplomat}|${mayAppoint}|${mayKick}|${myRole}|${isMe}`;
      if (!force && nextCtl === ctlKey) return;
      ctlKey = nextCtl;
      clear(controlsSlot);
      if (isMe || (!mayAppoint && !mayKick)) return;

      const box = el('div', { class: 'rctl' });
      box.appendChild(sectionHeader('CHAIN OF COMMAND'));
      const grid = el('div', { class: 'rctl__grid' });

      if (mayAppoint && row.role !== 'leader') {
        if (row.role === 'member') {
          grid.appendChild(
            holdButton('APPOINT OFFICER', {
              variant: 'primary',
              hint: 'hold to promote',
              onComplete: () => {
                void runAction('OFFICER APPOINTED', backend.setRole(playerId, 'officer'));
              },
            }),
          );
        } else {
          grid.appendChild(
            holdButton('DEMOTE', {
              variant: 'danger',
              hint: 'hold to demote',
              onComplete: () => {
                void runAction('OFFICER DEMOTED', backend.setRole(playerId, 'member'));
              },
            }),
          );
        }
      }

      if (mayAppoint && row.role !== 'leader') {
        grid.appendChild(
          holdButton('TRANSFER LEAD', {
            variant: 'danger',
            hint: 'hold — irreversible',
            holdMs: 1500,
            onComplete: () => {
              void runAction('LEADERSHIP TRANSFERRED', backend.transferLeadership(playerId));
            },
          }),
        );
      }

      // Officers may only remove plain members (mirrors kickMember).
      const canKickThis =
        mayKick && row.role !== 'leader' && !(myRole === 'officer' && row.role === 'officer');
      if (canKickThis) {
        grid.appendChild(
          holdButton('KICK', {
            variant: 'danger',
            hint: 'hold to remove',
            holdMs: 1200,
            onComplete: () => {
              void runAction('COMMANDER REMOVED', backend.kickMember(playerId));
            },
          }),
        );
      }

      if (mayAppoint && row.role === 'officer') {
        grid.appendChild(
          button(row.isDiplomat ? 'REVOKE DIPLOMAT' : 'GRANT DIPLOMAT', {
            variant: row.isDiplomat ? 'quiet' : 'ghost',
            small: true,
            onClick: () => {
              void runAction(
                row.isDiplomat ? 'DIPLOMACY REVOKED' : 'DIPLOMACY GRANTED',
                backend.setDiplomat(playerId, !row.isDiplomat),
              );
            },
          }),
        );
      }

      if (grid.childElementCount === 0) return;
      box.appendChild(grid);
      controlsSlot.appendChild(box);
    }

    function update(row: RosterRow, s: GameState, position: number): void {
      currentRow = row;
      rank.textContent = String(position + 1).padStart(2, '0');

      const nextMark = `${row.name}|${row.hue}|${row.bot}`;
      if (nextMark !== markKey) {
        markKey = nextMark;
        clear(markSlot);
        markSlot.appendChild(commanderMark(row, { me: isMe, bot: row.bot }));
      }

      const nextName = `${row.name}|${row.role}|${row.isDiplomat}`;
      if (nextName !== nameKey) {
        nameKey = nextName;
        clear(nameLine);
        nameLine.appendChild(el('span', { text: row.name }));
        if (row.role !== 'member') {
          nameLine.appendChild(
            roleBadge(ROLE_SHORT[row.role], row.role.toUpperCase(), ROLE_BADGE[row.role]),
          );
        }
        if (row.isDiplomat) nameLine.appendChild(roleBadge('DIPL', 'DIPLOMAT', 'ok'));
      }

      const status = row.online ? 'ONLINE' : fmtAgo(row.lastSeen, s.now).toUpperCase();
      const nextSub = `${row.online}|${status}|${row.hexCount}|${row.armyCount}|${row.unitCount}`;
      if (nextSub !== subKey) {
        subKey = nextSub;
        clear(subLine);
        subLine.appendChild(
          el('span', { class: row.online ? 'dot dot--on' : 'dot dot--off', aria: { hidden: 'true' } }),
        );
        subLine.appendChild(el('span', { text: status }));
        subLine.appendChild(el('span', { text: '·' }));
        subLine.appendChild(el('span', { text: `${row.hexCount} TILES` }));
        subLine.appendChild(el('span', { text: '·' }));
        subLine.appendChild(
          el('span', { text: `${row.armyCount} COL / ${row.unitCount} U` }),
        );
      }

      total.textContent = fmtNum(row.power.total);
      const sum = Math.max(1, row.power.unitPower + row.power.territoryPower);
      miniUnit.style.width = `${((row.power.unitPower / sum) * 100).toFixed(2)}%`;
      miniTerr.style.width = `${((row.power.territoryPower / sum) * 100).toFixed(2)}%`;

      refreshDrawer(s, row, false);
    }

    return { root: rootEl, update };
  }

  // ── list render ───────────────────────────────────────────────────────────
  function render(state: GameState): void {
    lastState = state;
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) {
      clear(list);
      views.clear();
      orderKey = '';
      list.appendChild(emptyState('◇', 'no guild register'));
      return;
    }

    const rows = sortRows(rosterOf(state, guildId), sortKey);
    capNote.textContent = `${rows.length} / ${GUILD.maxMembers}`;

    const nextOrder = rows.map((r) => r.playerId).join(',');
    if (nextOrder !== orderKey) {
      orderKey = nextOrder;
      const live = new Set(rows.map((r) => r.playerId));
      for (const [id, view] of views) {
        if (!live.has(id)) {
          view.root.remove();
          views.delete(id);
          open.delete(id);
        }
      }
      clear(list);
      for (const row of rows) {
        let view = views.get(row.playerId);
        if (!view) {
          view = buildRow(row.playerId, row, state);
          views.set(row.playerId, view);
        }
        list.appendChild(view.root);
      }
    }

    rows.forEach((row, i) => views.get(row.playerId)?.update(row, state, i));

    if (rows.length === 0) list.appendChild(emptyState('◇', 'the register is empty'));
  }

  return {
    el: root,
    sync(state: GameState): void {
      render(state);
    },
    dispose(): void {
      views.clear();
      open.clear();
      clear(list);
      lastState = null;
      orderKey = '';
    },
  };
}
